function filters(){modal='filters';const names={none:'Original',bw:'Schwarz-Weiß',sepia:'Sepia'},styles={none:'none',bw:'grayscale(1)',sepia:'sepia(1)'};dialog(`<header><h2>Filter auswählen</h2>${iconBtn('dismiss','Schließen','times')}</header><div class="filter-options">${settings.AllowedFilters.map(f=>`<button class="filter-option" data-filter="${f}"><img src="${photo?.filterPreview||photo?.url||'photo-sample.svg'}" alt="" style="filter:${styles[f]}">${names[f]}</button>`).join('')}</div><p>Das Original bleibt gespeichert.</p>`);}
function admin(needsPin){modal='admin';pin='';if(!needsPin){if(isEditor)adminMenu();else send('unlock',{pin:''});return;}dialog(`<h2>Admin-PIN</h2><div class="pin-display" aria-live="polite"></div><div class="keypad">${['1','2','3','4','5','6','7','8','9','clear','0','back'].map(n=>`<button data-key="${n}">${n==='clear'?'C':n==='back'?'←':n}</button>`).join('')}</div><p class="error-text" id="pin-error"></p><div class="actions">${btn('dismiss','Abbrechen','times')}${btn('unlock','Öffnen','unlock',true)}</div>`,true);}
function share(d){window.currentShare=d;busy(false);modal='share';if(d.fallback&&d.networkAvailable===false){dialog(`<h2>Download</h2><p>${esc(settings.LocalNetworkMissingText||'Bitte eine lokale WLAN-Verbindung herstellen.')}</p>${btn('dismiss','Schließen','times')}`,true);return;}if(d.fallback)notify(settings.NetworkFallbackText||'Bitte mit dem Fotobox-WLAN verbinden.');if(!d.wifi){dialog(`<header class="download-close">${iconBtn('dismiss','Schließen','times')}</header><section class="single-download" id="download-step"><img src="${d.qr}" alt="QR-Code zum Download"><p>${esc(settings.DownloadInstructions)}</p>${!d.isPublic&&!d.wifi?'<p class="mobile-data-hint">Für lokalen Download: Mobile Daten deaktivieren und im Fotobox-WLAN bleiben.</p>':''}${settings.ShowDownloadAlternative?`<small>${esc(new URL(d.url).origin)}<br>Code: ${esc(d.url.split('/').at(-1))}</small>`:''}</section>`);return;}const connected=!settings.WifiName;dialog(`<header class="download-close">${iconBtn('dismiss','Schließen','times')}</header>${d.fallback?`<p class="fallback-status">${esc(d.connection||'Öffentliche Verbindung nicht bereit.')} Bitte das Fotobox-WLAN verwenden.</p>`:''}<div class="share-columns"><section class="share-step ${connected?'done':''}" id="wifi-step"><h3>${esc(settings.WifiStepTitle)}</h3>${d.wifi?`<img src="${d.wifi}" alt="WLAN QR-Code">`:'<div class="qr-placeholder">WLAN manuell verbinden</div>'}<p>${esc(settings.WifiInstructions)}</p><p class="mobile-data-hint">Mobile Daten am Handy deaktivieren und im Fotobox-WLAN bleiben.</p>${btn('connected',settings.ConnectedLabel,'check',true)}</section><section class="share-step ${connected?'':'pending'}" id="download-step"><h3>${esc(settings.DownloadStepTitle)}</h3><img src="${d.qr}" alt="QR-Code zum Foto"><p>${esc(settings.DownloadInstructions)}</p>${settings.ShowDownloadAlternative?`<small>${esc(new URL(d.url).origin)}<br>Code: ${esc(d.url.split('/').at(-1))}</small>`:''}</section></div>`);}
function bind(root){bindTemplatePicker(root);root.querySelectorAll('[data-single-layout]').forEach(b=>b.onclick=()=>{if(isEditor){simulate(false);return;}send('singleLayout',{index:+b.dataset.singleLayout});});root.querySelectorAll('[data-select-id]').forEach(b=>b.onclick=()=>{if(locked||!selectionMode)return;const id=b.dataset.selectId;if(selectedPhotos.has(id))selectedPhotos.delete(id);else if(selectedPhotos.size<100)selectedPhotos.add(id);else{notify('Höchstens 100 Bilder auswählen.');return;}b.classList.toggle('selected',selectedPhotos.has(id));b.setAttribute('aria-pressed',selectedPhotos.has(id));b.querySelector('i').className='fa fa-'+(selectedPhotos.has(id)?'check-circle':'circle-thin');updateSelection();});root.querySelectorAll('[data-download-id]').forEach(b=>b.onclick=()=>{if(isEditor){notify('Downloads sind in der Vorschau nicht aktiv.');return;}send('galleryDownload',{id:b.dataset.downloadId});});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));root.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;const index=+b.dataset.layout;if(isEditor){previewLayout=index;simulate(true);}else send('layout',{index});});root.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{if(selectionMode){const selector=document.querySelector('[data-select-id="'+CSS.escape(b.dataset.id)+'"]');selector?.click();return;}viewerDirection='open';if(isEditor){photo=photos.find(p=>p.id===b.dataset.id)||photos[0];page='viewer';render();}else send('view',{id:b.dataset.id});});root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{const filter=b.dataset.filter,shareNext=autoSharePending;autoSharePending=false;dismiss();if(isEditor){const img=$('.result-photo');if(img)img.style.filter=filter==='bw'?'grayscale(1)':filter==='sepia'?'sepia(1)':'none';if(shareNext)setTimeout(previewShare,300);}else if(filter==='none'){if(shareNext)setTimeout(openShare,300);}else{shareAfterFilter=shareNext;busy(true,'Filter wird angewendet …');send('filter',{filter});}});root.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.key;pin=k==='clear'?'':k==='back'?pin.slice(0,-1):(pin+k).slice(0,8);$('.pin-display').textContent='•'.repeat(pin.length);$('#pin-error').textContent='';});}
function act(action){if(action==='allowAdminNetwork'){const b=document.getElementById('pairing-allow');if(b)b.disabled=true;const n=document.getElementById('pairing-status');if(n)n.textContent='Bitte die Windows-Administratorbestätigung an der Box bestätigen.';if(!isEditor)send('allowAdminNetwork');return;}if(action==='updates'){if(!isEditor)send('updateStatus');return;}if(action==='wifiOptions'){openKioskWifi();return;}if(action==='adminBack'){adminMenu();return;}if(['photo','collage','chooseTemplate','retry'].includes(action)&&!ready&&!locked){notify(settings.CameraUnavailableText||'Kamera nicht verbunden.');return;}if(action==='powerMenu'){showPowerMenu();return;}if(action==='powerConfirmShutdown'||action==='powerConfirmRestart'){confirmPower(action==='powerConfirmRestart'?'restart':'shutdown');return;}if(action==='doShutdown'||action==='doRestart'){if(!isEditor)send('systemPower',{action:action==='doRestart'?'restart':'shutdown'});return;}if(action==='activate'){if(isEditor){page='home';render();}else send('activate');return;}if(action==='chooseTemplate'){if(isEditor){page='templates';render();}else send('chooseTemplate');return;}
 if(isEditor&&!interactive&&action!=='dismiss')return;
 if(action==='nextCapture'){const review=$('.capture-review');if(!review)return;const index=Number(review.dataset.index);review.remove();if(isEditor&&window.previewNext){const next=window.previewNext;window.previewNext=null;next();}else send('nextCapture',{index});return;}if(action==='editorExit'){if(isEditor){dismiss();return;}send('editorExit');return;}if(action==='expandResult'){resultExpanded=!resultExpanded;$('#result').classList.toggle('expanded',resultExpanded);const media=$('#result .free-element[data-binding=photo]')||$('#result .free-element[data-binding=latest]')||$('#result .free-element[data-binding=slideshow]');if(media)media.classList.toggle('result-selected-media',resultExpanded);return;}if(action==='selectionMode'){selectionMode=true;suppressGalleryEntry=true;render();return;}if(action==='endSelection'){selectedPhotos.clear();selectionMode=false;suppressGalleryEntry=true;render();return;}if(action==='clearSelection'){if(locked)return;selectedPhotos.clear();rootSelection();return;}if(action==='closeGallery'){selectedPhotos.clear();selectionMode=false;action='home';}if(action==='downloadSelection'){if(locked)return;if(isEditor){notify('Downloads sind in der Vorschau nicht aktiv.');return;}if(!selectedPhotos.size)return;busy(true,'Download wird vorbereitet …');send('downloadSelection',{ids:[...selectedPhotos]});return;}
 if(action==='previous'||action==='next')viewerDirection=action;
 if(action==='dismiss'){dismiss();return;}
 if(action==='connected'){if($('#wifi-step'))$('#wifi-step').className='share-step done';if($('#download-step'))$('#download-step').className='share-step';return;}
 if(action==='unlock'){send('unlock',{pin});return;}
 if(locked&&action!=='cancel')return;
 if(action==='confirmDelete'){modal='delete';dialog(`<h2>${esc(settings.DeleteDialogTitle||'Foto entfernen?')}</h2><p>${esc(settings.DeleteDialogText||'Das Foto wird aus der Galerie entfernt.')}</p><div class="actions">${btn('dismiss',settings.DeleteCancelText||'Behalten','arrow-left')}${btn('delete',settings.DeleteConfirmText||'Entfernen','trash-o',false,'danger')}</div>`,true);return;}
 if(action==='delete'){dismiss();if(isEditor){page='home';render();}else send('delete');return;}
 if(action==='filters'){filters();return;}
 if(isEditor){if(action==='photo'){if(settings.ChooseSingleLayout&&settings.SingleTemplates.length>1){page='singleLayouts';render();}else simulate(false);return;}if(action==='collage'){if(settings.ChooseCollageLayout&&layouts().length>1){page='layouts';render();}else simulate(true);return;}if(action==='cancel'){previewTimers.forEach(clearTimeout);previewTimers=[];page='home';render();return;}if(action==='download'){notify('In der Vorschau werden keine Downloadlinks erzeugt.');return;}page=action==='gallery'?'gallery':'home';render();return;}
 if(action==='photo'||action==='collage'){locked=true;updateReady();}
 send(action);
}
function simulate(collage){page='capture';render();locked=true;let index=1,total=collage?layouts()[previewLayout].Slots.length:1;const next=()=>{receive({type:'progress',index,total});let remaining=collage?settings.CollageCountdown:settings.CountdownSeconds;count(String(remaining));const tick=()=>{remaining--;if(remaining>0){count(String(remaining));previewTimers.push(setTimeout(tick,1000));}else{receive({type:'shot',photo:{url:'sample.svg'},index,total});if(index++<total){if(settings.CollageConfirmNext){window.previewNext=next;reviewCapture({photo:{url:'photo-sample.svg'},index:index-1,total});}else previewTimers.push(setTimeout(next,700));}else{receive({type:'processing'});previewTimers.push(setTimeout(()=>{page='result';photo={url:'sample.svg'};render();startResultAutomation();},(settings.ShutterDurationMs??500)+(settings.ProcessingDelayMs??700)));}}};previewTimers.push(setTimeout(tick,1000));};next();}
function receive(d){
 if(d.type==='preview'){const signature=JSON.stringify(d);if(signature===lastPreviewSignature)return;lastPreviewSignature=signature;previewTimers.forEach(clearTimeout);previewTimers=[];dismiss();resultExpanded=false;captureProcessed=false;settings=d.settings;photos=previewPhotos();photo=photos[0];interactive=!!d.interactive;page=d.page==='selectionPreview'?'gallery':d.page==='downloadPreview'?'result':d.page==='idle'?'home':d.page;if(d.layoutIndex!==undefined)previewLayout=d.layoutIndex;idleSince=Date.now();selectionMode=d.page==='selectionPreview';ready=true;render();if(d.page==='capture'){if(interactive)simulate(false);else{count(String(settings.CountdownSeconds));const ring=$('.ring-progress');if(ring)ring.style.animationPlayState='paused';}}if(d.page==='idle')showIdle();if(d.page==='downloadPreview'){const qr='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240"><rect width="240" height="240" fill="white"/><text x="120" y="125" text-anchor="middle" font-family="sans-serif" font-size="20">QR-Vorschau</text></svg>');share({qr,wifi:settings.DownloadMode==='wifi'&&settings.WifiName?qr:null,url:'https://vorschau.invalid/p/BEISPIEL'});}}
 else if(d.type==='model'){const freshResult=d.page==='result'&&page==='capture',afterFilter=d.page==='result'&&shareAfterFilter;if(d.page!=='result'){autoSharePending=false;shareAfterFilter=false;}if(d.page!=='home')hideIdle();else idleSince=Date.now();document.querySelectorAll('.remote-preview-exit').forEach(e=>e.remove());if(d.page==='capture'){captureIndex=1;captureTotal=1;captureProcessed=false;}if(d.page==='capture'||d.page==='home'){selectedPhotos.clear();selectionMode=false;}resultExpanded=false;tunnelStatus=d.connection||tunnelStatus;settings=d.settings;window.templateUsage=d.templateUsage||{};page=d.page;photos=d.photos||[];photo=d.photo;ready=!!d.ready;dismiss();render();if(d.message&&$('#failure'))$('#failure').textContent=friendlyGuestFailure(d.message);if(freshResult)startResultAutomation();else if(afterFilter){shareAfterFilter=false;setTimeout(openShare,300);}}
 else if(d.type==='count')count(d.text);
 else if(d.type==='progress'){$('.capture-review')?.remove();$('#shot-strip').hidden=false;captureIndex=d.index;captureTotal=d.total;captureProcessed=false;$('#sequence').style.display=d.total>1?'block':'none';$('#sequence').textContent=`Bild ${d.index} von ${d.total}`;}
 else if(d.type==='shot'){captureIndex=d.index;captureTotal=d.total;captureProcessed=true;captureStatus();if(d.total>1){const img=new Image();img.src=d.photo.thumb||d.photo.url;img.alt='Aufnahme '+d.index;$('#shot-strip').append(img);}}
 else if(d.type==='processing'){if(page==='capture'){captureProcessed=true;count('');locked=true;const duration=settings.ShutterDurationMs??500;$('.screen')?.classList.add('processing-screen');$('#sequence').style.display='none';$('#shot-strip').hidden=true;const shutter=document.createElement('div');shutter.className='shutter-effect';shutter.style.animationDuration=duration+'ms';if(duration){$('#stage').append(shutter);setTimeout(()=>{shutter.remove();$('.processing-screen')?.classList.add('processing-ready');},duration);}else $('.processing-screen')?.classList.add('processing-ready');const prompt=$('.capture-prompt');if(prompt){prompt.hidden=false;prompt.innerHTML='<i class="fa fa-cog fa-spin"></i><span>'+esc(captureTotal>1?(settings.CollageProcessingText||'Collage wird verarbeitet …'):settings.CaptureProcessingText||'Bild wird verarbeitet …')+'</span>';}$('.capture-cancel')?.remove();updateReady();}else{count('');busy(true);}}
 else if(d.type==='readyState'){ready=!!d.ready;updateReady();}
 else if(d.type==='updateStatus'){if(!document.getElementById('update-overlay')){modal='updates';openAppUpdates(d.state,(cmd,extra)=>{send(cmd,extra);return Promise.resolve();},adminMenu);}else applyUpdateState(d.state);}
 else if(d.type==='updateProgress')applyUpdateState(d.state);
 else if(d.type==='updateError')appUpdateError(d.message);
 else if(d.type==='wifiStatus')kioskWifiResult(d);
 else if(d.type==='wifiError')kioskWifiError(d.message);
 else if(d.type==='powerPending'){busy(true,'Wird sauber beendet …');document.querySelectorAll('.system-dialog button').forEach(b=>b.disabled=true);}
 else if(d.type==='powerError'){busy(false);notify(d.message);showPowerMenu();}
 else if(d.type==='tunnel'){tunnelStatus=d.message;const n=document.querySelector('.connection-status');if(n)n.textContent=tunnelStatus;}
 else if(d.type==='share')share(d);
 else if(d.type==='escape')escapeKiosk();
 else if(d.type==='remotePairing')remotePairing(d);
 else if(d.type==='pairingStatus'){const node=document.getElementById('pairing-status');if(node)node.textContent=d.message;const b=document.getElementById('pairing-allow');if(b)b.disabled=false;}
 else if(d.type==='remotePreview'){document.querySelectorAll('.remote-preview-exit').forEach(e=>e.remove());receive({type:'preview',settings:d.settings,page:d.page,interactive:false});const banner=document.createElement('button');banner.className='btn remote-preview-exit';banner.textContent='Einrichtungsvorschau · zum Kiosk';banner.style.cssText='position:fixed;right:20px;top:20px;z-index:10000';banner.onclick=()=>{banner.remove();send('home');};document.body.append(banner);}
 else if(d.type==='cameraLost'){liveStream?.reset();const liveImage=$('.live-background');if(liveImage)liveImage.style.visibility='hidden';}
 else if(d.type==='cameraError')kioskCameraError(d.message);
 else if(d.type==='cameraOptions')showKioskCamera(d.camera);
 else if(d.type==='adminMenu')adminMenu();
 else if(d.type==='confirmNext')reviewCapture(d);
 else if(d.type==='admin'){admin(d.needsPin);if(settings.DownloadMode==='public'){const state=document.createElement('p');state.className='connection-status';state.textContent=tunnelStatus||'Öffentliche Verbindung wird vorbereitet …';document.querySelector('.dialog')?.append(state);}}
 else if(d.type==='pinError'){pin='';$('.pin-display').textContent='';$('#pin-error').textContent='PIN stimmt nicht. Erneut eingeben.';}
 else if(d.type==='notice'){busy(false);notify(d.message);}
}
if(isEditor){window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent)receive(e.data);});parent.postMessage({type:'guestReady'},location.origin);}else{window.chrome.webview.addEventListener('message',e=>receive(e.data));send('ready');}
let liveStream=null;if(!isEditor)liveStream=createLiveStream('https://live.local/frame.jpg',{interval:40,target:()=>$('.live-background'),active:()=>!modal&&!$('#idle-screen')});
$('#admin-corner').onclick=()=>{if(!settings?.HiddenAdminEntry||locked)return;const now=Date.now();if(now-lastTap>3000)taps=0;lastTap=now;if(++taps===5){taps=0;if(isEditor)admin(false);else send('admin');}};
function escapeKiosk(){if(modal)dismiss();else if(!locked){if(isEditor){page='home';render();}else send('escape');}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();escapeKiosk();}});
$('#stage').addEventListener('pointerdown',e=>{if(page==='viewer'&&!modal&&!e.target.closest('button'))swipeStart={x:e.clientX,y:e.clientY};});$('#stage').addEventListener('pointercancel',()=>swipeStart=null);$('#stage').addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.3){suppressTapUntil=Date.now()+500;act(dx>0?'previous':'next');}});$('#stage').addEventListener('click',e=>{if(page==='viewer'&&e.target.matches('.result-photo')&&Date.now()>suppressTapUntil&&!modal)$('.viewer')?.classList.toggle('controls-hidden');});
let lastActivity=0;function activity(){if(Date.now()-lastActivity>2000){lastActivity=Date.now();send('activity');}}document.addEventListener('pointerdown',activity);document.addEventListener('scroll',activity,true);




function galleryMarkup(){const list=photos;for(const id of selectedPhotos)if(!list.some(p=>p.id===id))selectedPhotos.delete(id);return `<section class="screen gallery ${settings.GalleryOverlayCaption?'caption-overlay':''}">${settings.GalleryBackgroundImage?`<img class="background-image" src="${media(settings.GalleryBackgroundImage)}" alt="">`:''}<div class="topbar"><div class="gallery-heading"><h1>${esc(settings.GalleryTitle||'Galerie')}</h1></div><div class="gallery-header-actions"><button class="btn" data-action="closeGallery"><span>Startseite</span><i class="fa fa-arrow-right"></i></button></div></div><div class="gallery-body">${list.map((p,i)=>`<article class="gallery-card"><button class="gallery__img" data-id="${esc(p.id)}"><figure>${isEditor?previewCanvas('gallery-preview'):`<img src="${p.thumb||p.url}" alt="Foto ${i+1}" loading="lazy">`}<figcaption>${settings.GalleryShowDate!==false?`<time><i class="fa fa-clock-o" aria-hidden="true"></i> ${esc(p.date)}</time>`:''}</figcaption></figure></button>${selectionMode&&settings.GalleryShowDownload&&(settings.ShowQr||settings.ShowDownload)?`<button class="card-select btn icon-btn ${selectedPhotos.has(p.id)?'selected':''}" data-select-id="${esc(p.id)}" aria-label="Foto ${i+1} auswählen" aria-pressed="${selectedPhotos.has(p.id)}"><i class="fa fa-${selectedPhotos.has(p.id)?'check-circle':'circle-thin'}" aria-hidden="true"></i></button>`:''}</article>`).join('')||'<p>Noch keine Fotos in diesem Event.</p>'}</div><div class="selection-bar" ${selectionMode?'':'hidden'}><span class="selection-count">${selectedPhotos.size} ausgewählt</span>${btn('downloadSelection','Herunterladen','qrcode')}${iconBtn('endSelection','Auswahl beenden','times')}</div>${!selectionMode&&settings.GalleryShowDownload&&(settings.ShowQr||settings.ShowDownload)?btn('selectionMode','Mehrere herunterladen','check-square-o',false,'selection-launch'):''}</section>`;}
function updateSelection(){const bar=$('.selection-bar');if(!bar)return;bar.hidden=!selectionMode;bar.querySelector('[data-action=downloadSelection]').disabled=!selectedPhotos.size;bar.querySelector('.selection-count').textContent=selectedPhotos.size+' ausgewählt';}
function rootSelection(){document.querySelectorAll('[data-select-id]').forEach(b=>{b.classList.toggle('selected',selectedPhotos.has(b.dataset.selectId));b.setAttribute('aria-pressed',selectedPhotos.has(b.dataset.selectId));b.querySelector('i').className='fa fa-'+(selectedPhotos.has(b.dataset.selectId)?'check-circle':'circle-thin');});updateSelection();}
function previewPhotos(){return [{id:'sample2',name:'261116_184200.jpg',url:'photo-sample.svg',date:'16.11.2026 · 18:42'},{id:'sample',name:'261116_184100.jpg',url:'photo-sample.svg',date:'16.11.2026 · 18:41'}].sort((a,b)=>settings.GalleryNewestFirst===false?a.date.localeCompare(b.date):b.date.localeCompare(a.date));}
function previewCanvas(cls){return `<canvas class="${cls}" data-preview-photo role="img" aria-label="Beispielbild mit gewähltem Rahmen"></canvas>`;}
function paintPreviews(){const generation=lastPreviewSignature;
 const template=settings.SingleTemplates?.[0];const t=template?{w:template.Width||1800,h:template.Height||1200,bg:template.Background,frame:template.Frame,left:template.Left,right:template.Right,top:template.Top,bottom:template.Bottom,caption:template.Caption,fit:template.Fit,placement:template.FramePlacement}:{w:settings.PhotoOutputWidth||1800,h:settings.PhotoOutputHeight||1200,bg:settings.PhotoBackground,frame:settings.PhotoFrame,left:settings.PhotoInsetLeft,right:settings.PhotoInsetRight,top:settings.PhotoInsetTop,bottom:settings.PhotoInsetBottom,caption:settings.PhotoCaption,fit:settings.PhotoFitMode,placement:settings.MediaPlacements?.PhotoFrame};
 const sample=new Image(),frame=new Image();let sampleReady=false,frameReady=!t.frame;
 const draw=()=>{if(generation!==lastPreviewSignature||!sampleReady||!frameReady)return;document.querySelectorAll('canvas[data-preview-photo]').forEach(c=>{c.width=Math.round(900*t.w/Math.max(t.w,t.h));c.height=Math.round(900*t.h/Math.max(t.w,t.h));const g=c.getContext('2d'),w=c.width,h=c.height;g.fillStyle=t.bg||'#191919';g.fillRect(0,0,w,h);const x=w*(t.left||0)/100,y=h*(t.top||0)/100,bw=w*(100-(t.left||0)-(t.right||0))/100,bh=h*(100-(t.top||0)-(t.bottom||0))/100,k=(t.fit===0?Math.max:Math.min)(bw/sample.width,bh/sample.height);g.save();g.beginPath();g.rect(x,y,bw,bh);g.clip();g.drawImage(sample,x+(bw-sample.width*k)/2,y+(bh-sample.height*k)/2,sample.width*k,sample.height*k);g.restore();if(t.frame&&frame.naturalWidth){const p=t.placement||{Fit:'contain',Scale:100,X:50,Y:50},k=(p.Fit==='cover'?Math.max:Math.min)(w/frame.width,h/frame.height)*(p.Scale||100)/100;g.drawImage(frame,(w-frame.width*k)*(p.X??50)/100,(h-frame.height*k)*(p.Y??50)/100,frame.width*k,frame.height*k);}if(t.caption){g.fillStyle=settings.PhotoCaptionColor||'#fff';g.font=(w*.022)+'px '+settings.FontName;g.textAlign='center';g.fillText(t.caption.replace('{event}',settings.Events?.find(e=>e.Id===settings.ActiveEvent)?.Name||''),w/2,h*.96,w*.92);}});};
 sample.onload=()=>{sampleReady=true;draw();};sample.src='photo-sample.svg';if(t.frame){frame.onload=()=>{frameReady=true;draw();};frame.onerror=()=>{frameReady=true;draw();};frame.src=media(t.frame);}
}
function adminMenu(){modal='admin';dialog(`<h2>Adminbereich</h2><div class="admin-menu-actions">${btn('dismiss','Zurück zum Kiosk','arrow-left')}${btn('remoteAdmin','Einrichtung über Smartphone','mobile')}${btn('cameraOptions','Kameraeinstellungen','camera')}${btn('wifiOptions','WLAN verbinden','wifi')}${btn('updates','Software & Updates','refresh')}${btn('powerMenu','Ausschalten / Neustarten','power-off')}${btn('editorExit','Zurück zum Editor','cog')}</div>`,true);}
function reviewCapture(d){count('');$('#shot-strip').hidden=true;$('.capture-review')?.remove();const review=document.createElement('div');review.className='capture-review';review.dataset.index=d.index;review.innerHTML=`<img src="${d.photo.url}" alt="Aufnahme ${d.index} von ${d.total}"><div class="review-next">${btn('nextCapture','Nächstes Foto','arrow-right')}</div>`;$('#stage').append(review);bind(review);}
function runtimeElement(e,layer){if((e.Kind==='button'||e.Kind==='clickarea')&&((e.Action==='photo'&&!settings.ShowSingle)||(e.Action==='collage'&&!settings.ShowCollage)||(e.Action==='gallery'&&!settings.ShowGallery)||(e.Action==='filters'&&!settings.FiltersEnabled)||(e.Action==='confirmDelete'&&!settings.ShowDelete)||(['download','selectionMode','downloadSelection'].includes(e.Action)&&!settings.ShowQr&&!settings.ShowDownload)))return;const n=document.createElement(e.Kind==='button'||e.Kind==='clickarea'?'button':'div');n.className='free-element '+(e.Kind==='button'?'btn':'');n.dataset.binding=e.Binding||'';Object.assign(n.style,{position:'absolute',left:e.X*100+'%',top:e.Y*100+'%',width:e.Width*100+'%',height:e.Height*100+'%',transform:'rotate('+(e.Rotation||0)+'deg)'});elementVisual(n,e,(layer.classList.contains('custom-share')?layer.clientWidth:innerWidth)/1280);if(e.Kind==='button'||e.Kind==='clickarea'){n.dataset.action=e.Action;if(e.Kind==='clickarea'){n.style.opacity='0';n.setAttribute('aria-label',e.Text||e.Action);}}
 if(e.Binding==='gallery'){const grid=layer._gallery;if(grid){n.append(grid);Object.assign(grid.style,{position:'absolute',inset:'0',padding:(e.GridPadding??8)+'px',top:'0',width:'100%',height:'100%'});}}
 else if(['photo','latest','slideshow'].includes(e.Binding)||e.Kind==='image'){const img=new Image();const latest=settings.GalleryNewestFirst!==false?photos[0]:photos.at(-1);const current=e.Binding==='photo'?(photo||latest):latest;const dynamic=['photo','latest','slideshow'].includes(e.Binding);if(dynamic){if(current?.url)img.src=current.url;else{const empty=document.createElement('span');empty.className='dynamic-empty';empty.textContent=isEditor?'Beispielbild':'Noch keine Aufnahmen';n.append(empty);img.hidden=true;}}else img.src=media(e.Image);if(e.Binding==='slideshow'&&e.SlideshowMode==='conveyor'){layer.append(n);slideCleanups.push(createConveyor(n,e,photos,{scale:innerWidth/1280}));return;}if(e.Binding==='slideshow'&&photos.length>1){let slide=settings.GalleryNewestFirst!==false?0:photos.length-1;slideTimers.push(setInterval(()=>{if(!img.isConnected||document.hidden)return;slide=(slide+1)%photos.length;img.src=photos[slide].url;},Math.max(2,e.SlideSeconds||6)*1000));}img.alt=e.Text||'Foto';img.style.cssText='width:100%;height:100%;object-fit:'+(e.ImageFit||'cover')+';pointer-events:auto;position:relative;transform:none';if(dynamic)img.className='result-photo';n.append(img);}
 else{if(e.Icon)n.innerHTML='<i class="fa fa-'+esc(e.Icon)+'" aria-hidden="true"></i>';const index=Math.max(0,photos.findIndex(p=>p.id===photo?.id));const text=e.Binding==='filename'?photo?.name:e.Binding==='date'?photo?.date:e.Binding==='counter'?((settings.GalleryNewestFirst!==false?photos.length-index:index+1)+' / '+photos.length):e.Text;const span=document.createElement('span');span.textContent=text||'';n.append(span);}layer.append(n);}
function applyCustomScreen(){if(!settings[designKey(page)]){if(page==='gallery'&&selectionMode&&settings.FreeSelectionDesign)customSelection();return;}const layer=document.createElement('div');layer.className='free-screen';const elements=visibleDesignItems(settings.ScreenElements.filter(e=>e.Page===page&&e.Visible!==false),settings).map(e=>presentedDesignItem(e,settings));if(page==='welcome'){const activation=$('.welcome-activate');if(elements.some(e=>['button','clickarea'].includes(e.Kind)&&e.Action==='activate'))activation?.remove();else if(activation)activation.innerHTML='';}if(page==='gallery'){$('.selection-launch')?.remove();layer._gallery=$('.gallery-body');$('.gallery .topbar')?.remove();}if(page==='home')document.querySelectorAll('.welcome,.start-actions,.click-area').forEach(n=>n.remove());if(page==='result')document.querySelectorAll('#result>.topbar,#result>.bottom-actions').forEach(n=>n.remove());if(page==='viewer')document.querySelectorAll('.viewer-name,.viewer-counter,.viewer-actions,.viewer-close,.previous,.next').forEach(n=>n.remove());if(elements.some(e=>['photo','latest','slideshow'].includes(e.Binding)))$('#stage>.screen>.result-photo')?.remove();for(const e of elements)runtimeElement(e,layer);$('#stage>.screen')?.append(layer);if(page==='gallery'&&selectionMode&&settings.FreeSelectionDesign)customSelection();}
function customSelection(){$('.selection-bar')?.remove();const layer=document.createElement('div');layer.className='free-screen selection-custom';for(const e of settings.ScreenElements.filter(e=>e.Page==='selection'&&e.Visible!==false))runtimeElement(e,layer);$('.gallery')?.append(layer);bind(layer);}
function customShare(){const dialog=$('.dialog'),d=window.currentShare;if(!dialog||!d||d.fallback)return;dialog.classList.add('custom-share');dialog.replaceChildren();for(const original of settings.ScreenElements.filter(e=>e.Page==='download'&&e.Visible!==false)){const e={...original};if(!d.wifi){if(e.Binding==='wifiqr'||e.Action==='connected'||e.X<.5)continue;if(e.Binding==='downloadqr'||e.Kind==='text')e.X=(1-e.Width)/2;}const layer=document.createElement('div');layer.className='share-custom-layer';if(e.Binding==='downloadqr'||e.Binding==='wifiqr'){const n=document.createElement('div');n.id=e.Binding==='wifiqr'?'wifi-step':'download-step';n.className='share-step '+(d.wifi&&e.Binding==='downloadqr'?'pending':'');Object.assign(n.style,{position:'absolute',left:e.X*100+'%',top:e.Y*100+'%',width:e.Width*100+'%',height:e.Height*100+'%'});const img=new Image();img.src=e.Binding==='wifiqr'?d.wifi:d.qr;img.style.cssText='width:100%!important;height:100%!important;object-fit:contain;background:white;margin:0;padding:8px';n.append(img);dialog.append(n);}else runtimeElement(e,dialog);}if(!d.isPublic){const hint=document.createElement('p');hint.className='custom-network-hint';hint.textContent='Mobile Daten deaktivieren · im Fotobox-WLAN bleiben';dialog.append(hint);}}
function styleStandardButtons(root,currentPage){const prefix=({home:'Home',result:'Result',gallery:'Gallery',viewer:'Viewer',download:'Download',selection:'Selection'})[currentPage];const base=settings[prefix+'ButtonStyle'];for(const n of root.querySelectorAll('button.btn:not(.free-element)')){if(n.closest('.system-dialog,.capture-cancel'))continue;const s=n.closest('.selection-bar')||n.matches('.selection-launch')?settings.SelectionButtonStyle:base;if(!s?.Enabled)continue;const put=(k,v)=>n.style.setProperty(k,v,'important');put('background',s.Transparent?'transparent':s.Background);put('color',s.Foreground);put('border',s.BorderWidth+'px solid '+s.BorderColor);put('border-radius',s.Radius+'px');put('backdrop-filter','blur('+s.Blur+'px)');put('opacity',s.Opacity/100);put('box-shadow',s.Shadow?'0 '+s.Shadow*.25+'px '+s.Shadow+'px #0006':'none');}}
function centerCountdownGlyph(glyph){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),font='600 128px '+JSON.stringify(settings.CountdownFontName||'Segoe UI');ctx.font=font;const m=ctx.measureText(glyph.textContent),left=m.actualBoundingBoxLeft??0,right=m.actualBoundingBoxRight??m.width,ascent=m.actualBoundingBoxAscent??100,descent=m.actualBoundingBoxDescent??0;glyph.setAttribute('x',115-(right-left)/2);glyph.setAttribute('y',115+(ascent-descent)/2);glyph.dataset.inkFont=font;glyph.dataset.inkCenterX='115';glyph.dataset.inkCenterY='115';}

function friendlyGuestFailure(message){if(/fokus|focus|scharf/i.test(message||''))return settings.FocusFailureText||'Die Kamera konnte nicht scharfstellen. Bitte erneut versuchen.';if(/speicher|space|disk|voll|gespeichert|schreib/i.test(message||''))return settings.StorageFailureText||'Foto konnte nicht gespeichert werden. Bitte den Betreiber informieren.';if(/getrennt|verbunden|erkannt|Livebild/i.test(message||''))return settings.CameraUnavailableText||'Kamera nicht verbunden.';return settings.CaptureFailureText||'Das Foto konnte nicht aufgenommen werden. Bitte erneut versuchen.';}
